goW(){return"SEO, \u0935\u093f\u091c\u094d\u091e\u093e\u092a\u0928 \u0914\u0930 \u0905\u092d\u093f\u092f\u093e\u0928 \u091c\u094b \u0935\u093f\u091c\u093c\u093f\u091f\u0930 \u0915\u094b \u0917\u094d\u0930\u093e\u0939\u0915 \u092c\u0928\u093e\u090f\u0901\u0964"},
goR(){return"\u0939\u092e \u0938\u0939\u0940 \u0932\u094b\u0917\u094b\u0902 \u0915\u094b \u0906\u092a\u0915\u0947 \u0926\u0930\u0935\u093e\u091c\u093c\u0947 \u0924\u0915 \u0932\u093e\u0924\u0947 \u0939\u0948\u0902 \u0914\u0930 \u0909\u0928\u094d\u0939\u0947\u0902 \u0939\u093e\u0901 \u0915\u0939\u0928\u0947 \u092e\u0947\u0902 \u092e\u0926\u0926 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902\u0964 \u0938\u0930\u094d\u091a \u0911\u092a\u094d\u091f\u093f\u092e\u093e\u0907\u091c\u093c\u0947\u0936\u0928, \u092a\u0947\u0921 \u0915\u0948\u0902\u092a\u0947\u0928 \u0914\u0930 \u090f\u0928\u093e\u0932\u093f\u091f\u093f\u0915\u094d\u0938 \u2014 \u0938\u092c \u0905\u0938\u0932\u0940 \u0935\u094d\u092f\u093e\u0935\u0938\u093e\u092f\u093f\u0915 \u0928\u0924\u0940\u091c\u094b\u0902 \u092a\u0930 \u092e\u093e\u092a\u0947 \u091c\u093e\u0924\u0947 \u0939\u0948\u0902\u0964"},
goS(){return"\u0938\u0930\u094d\u091a \u0907\u0902\u091c\u0928 \u0911\u092a\u094d\u091f\u093f\u092e\u093e\u0907\u091c\u093c\u0947\u0936\u0928 (SEO)"},
goT(){return"Google \u0914\u0930 \u0938\u094b\u0936\u0932 \u092e\u0940\u0921\u093f\u092f\u093e \u0935\u093f\u091c\u094d\u091e\u093e\u092a\u0928"},
goU(){return"\u0915\u0928\u094d\u0935\u0930\u094d\u091c\u093c\u0928 \u091f\u094d\u0930\u0948\u0915\u093f\u0902\u0917 \u0914\u0930 \u090f\u0928\u093e\u0932\u093f\u091f\u093f\u0915\u094d\u0938"},
goV(){return"\u0938\u0930\u0932 \u092d\u093e\u0937\u093e \u092e\u0947\u0902 \u092e\u093e\u0938\u093f\u0915 \u0930\u093f\u092a\u094b\u0930\u094d\u091f"},
gog(){return"AI \u0914\u0930 \u0911\u091f\u094b\u092e\u0947\u0936\u0928"},
gof(){return"\u091a\u0948\u091f\u092c\u0949\u091f \u0914\u0930 \u0911\u091f\u094b\u092e\u0947\u0936\u0928 \u091c\u094b \u0939\u0930 \u0939\u092b\u093c\u094d\u0924\u0947 \u0918\u0902\u091f\u094b\u0902 \u092c\u091a\u093e\u090f\u0901\u0964"},
goa(){return"\u0906\u0930\u094d\u091f\u093f\u092b\u093c\u093f\u0936\u093f\u092f\u0932 \u0907\u0902\u091f\u0947\u0932\u093f\u091c\u0947\u0902\u0938 \u0915\u094b \u0935\u094d\u092f\u093e\u0935\u0939\u093e\u0930\u093f\u0915 \u0915\u093e\u092e \u092e\u0947\u0902 \u0932\u0917\u093e\u090f\u0901: \u0917\u094d\u0930\u093e\u0939\u0915\u094b\u0902 \u0915\u094b \u091c\u0935\u093e\u092c \u0926\u0947\u0928\u0947 \u0935\u093e\u0932\u0947 \u0905\u0938\u093f\u0938\u094d\u091f\u0947\u0902\u091f, \u0926\u094b\u0939\u0930\u093e\u090f \u091c\u093e\u0928\u0947 \u0935\u093e\u0932\u0947 \u0915\u093e\u092e \u0939\u091f\u093e\u0928\u0947 \u0935\u093e\u0932\u0947 \u0911\u091f\u094b\u092e\u0947\u0936\u0928, \u0914\u0930 \u0924\u0947\u091c\u093c \u092b\u093c\u0948\u0938\u0932\u094b\u0902 \u092e\u0947\u0902 \u092e\u0926\u0926 \u0915\u0930\u0928\u0947 \u0935\u093e\u0932\u0940 \u091c\u093e\u0928\u0915\u093e\u0930\u0940\u0964"},
gob(){return"\u0935\u0947\u092c\u0938\u093e\u0907\u091f \u0914\u0930 WhatsApp \u0915\u0947 \u0932\u093f\u090f AI \u091a\u0948\u091f \u0905\u0938\u093f\u0938\u094d\u091f\u0947\u0902\u091f"},
goc(){return"\u0906\u092a\u0915\u0947 \u091f\u0942\u0932\u094d\u0938 \u0915\u0947 \u092c\u0940\u091a \u0935\u0930\u094d\u0915\u092b\u093c\u094d\u0932\u094b \u0911\u091f\u094b\u092e\u0947\u0936\u0928"},
god(){return"\u0926\u0938\u094d\u0924\u093e\u0935\u0947\u091c\u093c \u0914\u0930 \u0921\u0947\u091f\u093e \u092a\u094d\u0930\u094b\u0938\u0947\u0938\u093f\u0902\u0917"},
