gp6(){return"\u0915\u0902\u091f\u0947\u0902\u091f, \u0930\u0940\u0932\u094d\u0938 \u0914\u0930 \u0915\u092e\u094d\u092f\u0941\u0928\u093f\u091f\u0940 \u092a\u094d\u0930\u092c\u0902\u0927\u0928 \u091c\u094b \u0935\u092b\u093c\u093e\u0926\u093e\u0930\u0940 \u092c\u0922\u093c\u093e\u090f\u0901\u0964"},
goY(){return"\u0939\u092e \u0906\u092a\u0915\u0940 \u0906\u0935\u093e\u091c\u093c \u092e\u0947\u0902 \u0915\u0902\u091f\u0947\u0902\u091f \u0915\u0940 \u092f\u094b\u091c\u0928\u093e \u092c\u0928\u093e\u0924\u0947, \u0909\u0938\u0947 \u0924\u0948\u092f\u093e\u0930 \u0915\u0930\u0924\u0947 \u0914\u0930 \u092a\u094d\u0930\u0915\u093e\u0936\u093f\u0924 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902 \u091c\u093f\u0938\u0938\u0947 \u0906\u092a\u0915\u0947 \u0926\u0930\u094d\u0936\u0915 \u092c\u0922\u093c\u0947\u0902: \u092a\u094b\u0938\u094d\u091f, \u0930\u0940\u0932\u094d\u0938, \u092b\u093c\u094b\u091f\u094b\u0917\u094d\u0930\u093e\u092b\u093c\u0940 \u0914\u0930 \u0930\u094b\u091c\u093c \u0915\u093e \u0915\u092e\u094d\u092f\u0941\u0928\u093f\u091f\u0940 \u092a\u094d\u0930\u092c\u0902\u0927\u0928\u0964"},
goZ(){return"\u092e\u093e\u0938\u093f\u0915 \u0915\u0902\u091f\u0947\u0902\u091f \u0915\u0948\u0932\u0947\u0902\u0921\u0930"},
gp_(){return"\u0930\u0940\u0932\u094d\u0938, \u092e\u094b\u0936\u0928 \u0917\u094d\u0930\u093e\u092b\u093c\u093f\u0915\u094d\u0938 \u0914\u0930 \u092b\u093c\u094b\u091f\u094b\u0917\u094d\u0930\u093e\u092b\u093c\u0940"},
gp0(){return"\u0915\u092e\u094d\u092f\u0941\u0928\u093f\u091f\u0940 \u092a\u094d\u0930\u092c\u0902\u0927\u0928"},
gp5(){return"\u0917\u094d\u0930\u094b\u0925 \u0914\u0930 \u090f\u0902\u0917\u0947\u091c\u092e\u0947\u0902\u091f \u0930\u093f\u092a\u094b\u0930\u094d\u091f"},
