goh(){return"\u0939\u092e \u0938\u0941\u0930\u0915\u094d\u0937\u093f\u0924 API \u0921\u093f\u091c\u093c\u093e\u0907\u0928 \u0914\u0930 \u0935\u093f\u0915\u0938\u093f\u0924 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902 \u0914\u0930 \u0906\u092a\u0915\u0947 \u0935\u094d\u092f\u0935\u0938\u093e\u092f \u0915\u094b \u0909\u0928 \u0938\u0947\u0935\u093e\u0913\u0902 \u0938\u0947 \u091c\u094b\u0921\u093c\u0924\u0947 \u0939\u0948\u0902 \u091c\u093f\u0928 \u092a\u0930 \u0935\u0939 \u0928\u093f\u0930\u094d\u092d\u0930 \u0939\u0948: \u092a\u0947\u092e\u0947\u0902\u091f, \u0936\u093f\u092a\u093f\u0902\u0917, CRM, ERP \u0914\u0930 \u092d\u0940 \u092c\u0939\u0941\u0924 \u0915\u0941\u091b\u0964"},
goi(){return"REST \u0914\u0930 GraphQL API \u0921\u093f\u091c\u093c\u093e\u0907\u0928"},
goj(){return"\u092a\u0947\u092e\u0947\u0902\u091f, \u0936\u093f\u092a\u093f\u0902\u0917 \u0914\u0930 CRM \u0907\u0902\u091f\u0940\u0917\u094d\u0930\u0947\u0936\u0928"},
gol(){return"\u0938\u0941\u0930\u0915\u094d\u0937\u093f\u0924 \u0911\u0925\u0947\u0902\u091f\u093f\u0915\u0947\u0936\u0928 \u0914\u0930 \u090f\u0915\u094d\u0938\u0947\u0938 \u0915\u0902\u091f\u094d\u0930\u094b\u0932"},
gom(){return"\u0921\u0949\u0915\u094d\u092f\u0942\u092e\u0947\u0902\u091f\u0947\u0936\u0928 \u0914\u0930 \u092e\u0949\u0928\u093f\u091f\u0930\u093f\u0902\u0917"},
gov(){return"\u0915\u094d\u0932\u093e\u0909\u0921 \u0914\u0930 IT \u0907\u0928\u094d\u092b\u094d\u0930\u093e\u0938\u094d\u091f\u094d\u0930\u0915\u094d\u091a\u0930"},
gou(){return"\u0915\u094d\u0932\u093e\u0909\u0921, DevOps \u0914\u0930 IT \u091c\u094b \u0906\u092a\u0915\u0947 \u092c\u0922\u093c\u0924\u0947 \u0938\u092e\u092f \u092d\u0940 \u091a\u0932\u0924\u0947 \u0930\u0939\u0947\u0902\u0964"},
gop(){return"\u0939\u092e \u092a\u094d\u0930\u092e\u0941\u0916 \u0915\u094d\u0932\u093e\u0909\u0921 \u092a\u0930 \u092d\u0930\u094b\u0938\u0947\u092e\u0902\u0926 \u0907\u0928\u094d\u092b\u094d\u0930\u093e\u0938\u094d\u091f\u094d\u0930\u0915\u094d\u091a\u0930 \u0921\u093f\u091c\u093c\u093e\u0907\u0928 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902, \u0921\u093f\u092a\u094d\u0932\u0949\u092f\u092e\u0947\u0902\u091f \u0915\u094b \u0911\u091f\u094b\u092e\u0947\u091f \u0915\u0930\u0924\u0947 \u0939\u0948\u0902, \u0914\u0930 \u0906\u092a\u0915\u0947 \u0938\u093f\u0938\u094d\u091f\u092e \u092a\u0930 \u091a\u094c\u092c\u0940\u0938\u094b\u0902 \u0918\u0902\u091f\u0947 \u0928\u091c\u093c\u0930 \u0930\u0916\u0924\u0947 \u0939\u0948\u0902 \u0924\u093e\u0915\u093f \u0938\u092e\u0938\u094d\u092f\u093e\u090f\u0901 \u0915\u093f\u0938\u0940 \u0915\u0947 \u0927\u094d\u092f\u093e\u0928 \u092e\u0947\u0902 \u0906\u0928\u0947 \u0938\u0947 \u092a\u0939\u0932\u0947 \u0920\u0940\u0915 \u0939\u094b \u091c\u093e\u090f\u0901\u0964"},
goq(){return"\u0915\u094d\u0932\u093e\u0909\u0921 \u0906\u0930\u094d\u0915\u093f\u091f\u0947\u0915\u094d\u091a\u0930 \u0914\u0930 \u092e\u093e\u0907\u0917\u094d\u0930\u0947\u0936\u0928"},
gor(){return"CI/CD \u092a\u093e\u0907\u092a\u0932\u093e\u0907\u0928 \u0914\u0930 DevOps"},
gos(){return"\u092e\u0949\u0928\u093f\u091f\u0930\u093f\u0902\u0917, \u092c\u0948\u0915\u0905\u092a \u0914\u0930 \u0930\u093f\u0915\u0935\u0930\u0940"},
got(){return"\u0932\u093e\u0917\u0924 \u0905\u0928\u0941\u0915\u0942\u0932\u0928"},
gvw(){return"Infinitility \u0939\u0940 \u0915\u094d\u092f\u094b\u0902"},
gvx(){return"\u091b\u0939 \u0935\u093e\u0926\u0947 \u091c\u094b \u0939\u092e \u0928\u093f\u092d\u093e\u0924\u0947 \u0939\u0948\u0902"},
gvl(){return"\u0938\u093f\u0926\u094d\u0927 \u0935\u093f\u0936\u0947\u0937\u091c\u094d\u091e\u0924\u093e"},
gvk(){return"\u0921\u093f\u091c\u093c\u093e\u0907\u0928, \u0915\u094b\u0921 \u0914\u0930 \u0917\u094d\u0930\u094b\u0925 \u092e\u0947\u0902 \u0935\u0930\u094d\u0937\u094b\u0902 \u0915\u0947 \u0935\u094d\u092f\u093e\u0935\u0939\u093e\u0930\u093f\u0915 \u0905\u0928\u0941\u092d\u0935 \u0935\u093e\u0932\u0940 \u0915\u0941\u0936\u0932 \u091f\u0940\u092e\u0964"},
gvn(){return"\u0938\u092e\u092f \u092a\u0930 \u0921\u093f\u0932\u0940\u0935\u0930\u0940"},
