gp7(){return"\u0421\u043e\u0446\u0441\u0435\u0442\u0438 \u0438 \u043a\u043e\u043d\u0442\u0435\u043d\u0442"},
gp6(){return"\u041a\u043e\u043d\u0442\u0435\u043d\u0442, \u0440\u0438\u043b\u0441 \u0438 \u0440\u0430\u0431\u043e\u0442\u0430 \u0441 \u0441\u043e\u043e\u0431\u0449\u0435\u0441\u0442\u0432\u043e\u043c, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u0443\u043a\u0440\u0435\u043f\u043b\u044f\u044e\u0442 \u043b\u043e\u044f\u043b\u044c\u043d\u043e\u0441\u0442\u044c."},
goY(){return"\u041c\u044b \u043f\u043b\u0430\u043d\u0438\u0440\u0443\u0435\u043c, \u0441\u043e\u0437\u0434\u0430\u0451\u043c \u0438 \u043f\u0443\u0431\u043b\u0438\u043a\u0443\u0435\u043c \u043a\u043e\u043d\u0442\u0435\u043d\u0442 \u0432 \u0432\u0430\u0448\u0435\u043c \u0441\u0442\u0438\u043b\u0435 \u0438 \u0440\u0430\u0441\u0442\u0438\u043c \u0432\u0430\u0448\u0443 \u0430\u0443\u0434\u0438\u0442\u043e\u0440\u0438\u044e: \u043f\u043e\u0441\u0442\u044b, \u0440\u0438\u043b\u0441, \u0444\u043e\u0442\u043e\u0441\u044a\u0451\u043c\u043a\u0430 \u0438 \u0435\u0436\u0435\u0434\u043d\u0435\u0432\u043d\u0430\u044f \u0440\u0430\u0431\u043e\u0442\u0430 \u0441 \u0441\u043e\u043e\u0431\u0449\u0435\u0441\u0442\u0432\u043e\u043c."},
goZ(){return"\u0415\u0436\u0435\u043c\u0435\u0441\u044f\u0447\u043d\u044b\u0435 \u043a\u043e\u043d\u0442\u0435\u043d\u0442-\u043f\u043b\u0430\u043d\u044b"},
gp_(){return"\u0420\u0438\u043b\u0441, \u043c\u043e\u0443\u0448\u043d-\u0433\u0440\u0430\u0444\u0438\u043a\u0430 \u0438 \u0444\u043e\u0442\u043e\u0441\u044a\u0451\u043c\u043a\u0430"},
